ee:message.ee:set-payload:
%dw 2.0
output application/json

var policyNumber = vars.requestData.queryParams.policyNumber
var flagPolicyNumber = policyNumber != null and policyNumber != ""

---

if (flagPolicyNumber) (
    if (sizeOf("SELECT name, policyNumber__c, addressUpdateStatus__c, address_zh__c, addrLine1__c, addrLine2__c, addrLine3__c, addrLine4__c, emailAddress__c, emailUpdateStatus__c, mobileNumberUpdateStatus__c, mobileNumber__c FROM customerContact__c WHERE policyNumber__c = '$(policyNumber)'") > 0) (
        "SELECT name, policyNumber__c, addressUpdateStatus__c, address_zh__c, addrLine1__c, addrLine2__c, addrLine3__c, addrLine4__c, emailAddress__c, emailUpdateStatus__c, mobileNumberUpdateStatus__c, mobileNumber__c FROM customerContact__c WHERE policyNumber__c = '$(policyNumber)'"
    ) else ("Wrong policy number, please provide the correct policy number")
) else ("Please enter your policy number")
